/**
 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`. Opting into the digest is what suppresses the immediate
 * emails, so the two lists are two views of the same preference. A suspended
 * member is skipped — their unread notifications wait and digest normally
 * once they are reinstated.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const subscribers = await preferenceRepo.listDigestSubscribers(orgId);
  const eligible: UserId[] = [];

  for (const userId of subscribers) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member && member.status !== "suspended") {
      eligible.push(userId);
    }
  }

  return eligible;
}

