import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { emit, subscribe } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as notificationService from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/9a236222-504b-4872-b43a-18ab0a1c3707/tests/server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("smoke: suspension", () => {
  it("suspends, blocks work/mentions/notifications, then reinstates", async () => {
    const tenant = await createTenant("suspend-smoke", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("missing");

    const before = await usageRepo.recomputeUsage(tenant.org.id);

    const suspended = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended.status).toBe("suspended");

    const after = await usageRepo.recomputeUsage(tenant.org.id);
    expect(after.seatsUsed).toBe(before.seatsUsed);

    // no actor resolvable
    const actor = await memberService.resolveActor(tenant.userIds.member, tenant.org.id);
    expect(actor).toBeNull();

    // cannot assign new issue to them
    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
      ),
    ).rejects.toBeInstanceOf(memberService.MemberSuspendedError);

    // mentions dropped
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {}),
    );
    const handle = tenant.userIds.member; // not used for handle but keep for clarity
    void handle;
    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hey @member check this",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    } as never);
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.member);

    // no notification
    const rows = await notificationService.notify(tenant.org.id, "member_joined", [tenant.userIds.member], {
      title: "t",
      body: "b",
      href: "/x",
      actorId: null,
    });
    expect(rows).toHaveLength(0);

    // reinstate
    const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(reinstated.status).toBe("active");

    const actor2 = await memberService.resolveActor(tenant.userIds.member, tenant.org.id);
    expect(actor2).not.toBeNull();
  });

  it("refuses suspending the last owner and self-suspend", async () => {
    const tenant = await createTenant("suspend-smoke-owner", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("missing");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/yourself|at least one owner/);

    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!adminMember) throw new Error("missing");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/cannot suspend/);
  });
});

